"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Forude: »Operationsstuen«. Direktøren siger, at operationen gik godt – patienten er bare ikke vågnet endnu.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Forude: »Havbunden«. Under havnen er der endnu en by, og dens port er en mund.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Forude: »Kundskabens træ«. Det husker alt, der nogensinde er sket i skoven, og vil ikke huske mere.",
